  comuna: string | null
  telefono: string | null
  email: string | null
  banco: {
    id: number
    nombre: string
  } | null
  bancos?: Array<{
    banco: {
      id: number
      nombre: string
    }
  }>
  createdAt: string
}

interface Banco {
