    if (parsed.data.bancoIds && parsed.data.bancoIds.length > 0) {
      // Verificar que todos los bancos pertenezcan a la oficina del usuario
      const bancos = await prisma.banco.findMany({
        where: {
          id: { in: parsed.data.bancoIds },
